from pathlib import Path
import base64,zlib,hashlib
TARGET='games-beyond/app.js'
DATA=''
EXPECTED='030ea03cf3e1253c65063ec10c29d5fe205dade8ba08f84f75b82fa058c355a3'
raw=zlib.decompress(base64.b64decode(DATA))
assert hashlib.sha256(raw).hexdigest()==EXPECTED
p=Path(TARGET);p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
print(TARGET,len(raw),EXPECTED)
